```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

struct Zawodnik {
    string imie;
    int czas;
};

int main() {
    ifstream plik("wyscig.txt");
    vector<Zawodnik> zaw;
    string imie;
    int czas;
    while (plik >> imie >> czas) {
        zaw.push_back({imie, czas});
    }

    sort(zaw.begin(), zaw.end(), [](const Zawodnik &a, const Zawodnik &b) {
        return a.czas < b.czas;
    });

    cout << "a) Ranking:" << endl;
    for (int i = 0; i < (int)zaw.size(); i++) {
        cout << "   " << i + 1 << ". " << zaw[i].imie << ": " << zaw[i].czas << " s" << endl;
    }

    int mediana = zaw[zaw.size() / 2].czas;
    cout << endl << "b) Mediana czasu: " << mediana << " s" << endl;

    cout << endl << "c) Ponizej mediany:" << endl;
    for (auto &z : zaw) {
        if (z.czas < mediana) {
            cout << "   " << z.imie << ": " << z.czas << " s" << endl;
        }
    }
    return 0;
}
```

